from functools import lru_cache
from itertools import combinations


GROUP_PRICE = (None, 800, 1520, 2160, 2560, 3000)


def total(basket):
    counts = [0] * 5
    for book in basket:
        counts[book - 1] += 1
    return _min_cost(tuple(counts))


@lru_cache(maxsize=None)
def _min_cost(counts):
    if not any(counts):
        return 0

    available = [index for index, count in enumerate(counts) if count]
    best = None

    for group_size in range(1, len(available) + 1):
        for group in combinations(available, group_size):
            remaining = list(counts)
            for index in group:
                remaining[index] -= 1
            price = GROUP_PRICE[group_size] + _min_cost(tuple(remaining))
            if best is None or price < best:
                best = price

    return best

